#!/bin/bash
###############################################################################
#  PsiphonLinux - Instalador Automatico Autossuficiente (single-file)
#  ---------------------------------------------------------------------------
#  Este unico arquivo contem o binario do Psiphon embutido (base64) e faz
#  TUDO automaticamente: instala, configura, executa e desinstala.
#
#  Uso:
#     sudo ./psiphon-linux-setup.sh              -> instala tudo
#     sudo ./psiphon-linux-setup.sh --start      -> instala e ja inicia o VPN
#     sudo ./psiphon-linux-setup.sh run          -> apenas inicia o VPN
#     sudo ./psiphon-linux-setup.sh status       -> verifica a instalacao
#     sudo ./psiphon-linux-setup.sh uninstall    -> remove tudo
#     ./psiphon-linux-setup.sh help              -> mostra esta ajuda
#
#  Baseado em SpherionOS/PsiphonLinux. Bugs de tratamento de erro corrigidos.
###############################################################################

set -euo pipefail

# ----------------------------- Configuracoes -------------------------------
INSTALL_DIR="/etc/psiphon"
BINARY_NAME="psiphon-tunnel-core-x86_64"
BINARY_PATH="${INSTALL_DIR}/${BINARY_NAME}"
CONFIG_PATH="${INSTALL_DIR}/psiphon.config"
STARTUP_PATH="/usr/bin/psiphon"
PAYLOAD_MARKER="__BINARY_PAYLOAD_BELOW__"

# Cores para saida (desativadas se nao houver terminal)
if [ -t 1 ]; then
  C_OK="\033[1;32m"; C_ERR="\033[1;31m"; C_INFO="\033[1;36m"; C_WARN="\033[1;33m"; C_RST="\033[0m"
else
  C_OK=""; C_ERR=""; C_INFO=""; C_WARN=""; C_RST=""
fi

log()  { echo -e "${C_INFO}[*]${C_RST} $*"; }
ok()   { echo -e "${C_OK}[OK]${C_RST} $*"; }
err()  { echo -e "${C_ERR}[ERRO]${C_RST} $*" >&2; }
warn() { echo -e "${C_WARN}[!]${C_RST} $*"; }

# ----------------------------- Utilitarios ---------------------------------
require_root() {
  if [ "$(id -u)" -ne 0 ]; then
    err "Este comando precisa ser executado como root. Use: sudo $0 $*"
    exit 1
  fi
}

check_arch() {
  local arch
  arch="$(uname -m)"
  if [ "$arch" != "x86_64" ] && [ "$arch" != "amd64" ]; then
    warn "Arquitetura detectada: '$arch'. O binario embutido e apenas para x86_64/amd64."
    warn "O programa provavelmente NAO funcionara nesta maquina."
  fi
}

# Extrai o binario embutido (apos o marcador) e decodifica de base64
extract_binary() {
  log "Extraindo binario embutido para ${BINARY_PATH} ..."
  # Pega tudo apos a linha do marcador e decodifica
  sed -e "1,/^${PAYLOAD_MARKER}$/d" "$0" | base64 -d > "${BINARY_PATH}"
  chmod +x "${BINARY_PATH}"

  # Verifica integridade via SHA256
  local expected="bff7a999b4d749ccad2fa79ee9f7dc805cf44ece40875d43936c15a40f30ad83"
  if command -v sha256sum >/dev/null 2>&1; then
    local actual
    actual="$(sha256sum "${BINARY_PATH}" | awk '{print $1}')"
    if [ "$actual" = "$expected" ]; then
      ok "Verificacao de integridade (SHA256) do binario: OK"
    else
      err "SHA256 do binario nao confere!"
      err "  esperado: $expected"
      err "  obtido:   $actual"
      exit 1
    fi
  else
    warn "sha256sum nao encontrado; pulando verificacao de integridade."
  fi
}

write_config() {
  log "Gravando arquivo de configuracao em ${CONFIG_PATH} ..."
  cat > "${CONFIG_PATH}" <<'PSIPHON_CONFIG_EOF'
{
"LocalHttpProxyPort":8081,
"LocalSocksProxyPort":1081,
"EgressRegion":"US",
"PropagationChannelId":"FFFFFFFFFFFFFFFF",
"RemoteServerListDownloadFilename":"remote_server_list",
"RemoteServerListSignaturePublicKey":"",
"RemoteServerListUrl":"https://s3.amazonaws.com//psiphon/web/mjr4-p23r-puwl/server_list_compressed",
"SponsorId":"FFFFFFFFFFFFFFFF",
"UseIndistinguishableTLS":true
}
PSIPHON_CONFIG_EOF
}

write_startup_script() {
  log "Instalando comando de inicializacao em ${STARTUP_PATH} ..."
  cat > "${STARTUP_PATH}" <<PSIPHON_STARTUP_EOF
#!/bin/bash
# Inicia o Psiphon tunnel-core usando a configuracao instalada.
exec "${BINARY_PATH}" -config "${CONFIG_PATH}"
PSIPHON_STARTUP_EOF
  chmod +x "${STARTUP_PATH}"
}

post_install_checks() {
  echo " "
  log "Executando verificacoes pos-instalacao"
  echo " "
  log "Fase 1/2: verificando se os arquivos existem"

  local fail=0

  if [ -f "${BINARY_PATH}" ]; then
    ok "Binario do Psiphon encontrado"
  else
    err "Binario do Psiphon NAO encontrado"; fail=1
  fi

  if [ -f "${CONFIG_PATH}" ]; then
    ok "Configuracao do Psiphon encontrada"
  else
    err "Configuracao do Psiphon NAO encontrada"; fail=1
  fi

  if [ -f "${STARTUP_PATH}" ]; then
    ok "Script de inicializacao encontrado"
  else
    err "Script de inicializacao NAO encontrado"; fail=1
  fi

  echo " "
  log "Fase 2/2: verificando permissoes de execucao"

  if [ -x "${BINARY_PATH}" ]; then
    ok "Binario com permissoes corretas"
  else
    err "Binario sem as permissoes necessarias"; fail=1
  fi

  if [ -x "${STARTUP_PATH}" ]; then
    ok "Script de inicializacao com permissoes corretas"
  else
    err "Script de inicializacao sem as permissoes necessarias"; fail=1
  fi

  if [ "$fail" -ne 0 ]; then
    err "Instalacao concluida com problemas. Verifique as mensagens acima."
    exit 1
  fi
}

# ----------------------------- Acoes ---------------------------------------
do_install() {
  require_root "$@"
  check_arch
  log "Iniciando instalacao do PsiphonLinux"

  mkdir -p "${INSTALL_DIR}"
  extract_binary
  write_config
  write_startup_script
  post_install_checks

  echo " "
  ok "PsiphonLinux instalado com sucesso!"
  echo -e "    - Proxy HTTP/HTTPS: ${C_INFO}127.0.0.1:8081${C_RST}"
  echo -e "    - Proxy SOCKS4/5:   ${C_INFO}127.0.0.1:1081${C_RST}"
  echo " "
  echo "    Para iniciar:  sudo psiphon    (ou: sudo $0 run)"
  echo "    A primeira conexao pode demorar um pouco. Aguarde."
}

do_run() {
  require_root run
  if [ ! -x "${BINARY_PATH}" ]; then
    err "Psiphon nao esta instalado. Rode primeiro: sudo $0 install"
    exit 1
  fi
  check_arch
  log "Iniciando o Psiphon (Ctrl+C para parar)..."
  exec "${BINARY_PATH}" -config "${CONFIG_PATH}"
}

do_status() {
  log "Status da instalacao do PsiphonLinux:"
  local all_ok=1
  for f in "${BINARY_PATH}" "${CONFIG_PATH}" "${STARTUP_PATH}"; do
    if [ -e "$f" ]; then
      ok "presente: $f"
    else
      err "ausente:  $f"; all_ok=0
    fi
  done
  if [ "$all_ok" -eq 1 ]; then
    ok "Psiphon esta instalado. Rode 'sudo psiphon' para conectar."
  else
    warn "Instalacao incompleta ou ausente. Rode: sudo $0 install"
  fi
}

do_uninstall() {
  require_root uninstall
  log "Removendo PsiphonLinux..."
  rm -rf "${INSTALL_DIR}"
  rm -f  "${STARTUP_PATH}"
  rm -f  "ca.psiphon.PsiphonTunnel.tunnel-core" 2>/dev/null || true
  ok "PsiphonLinux removido com sucesso."
}

show_help() {
  sed -n '2,17p' "$0" | sed 's/^#\s\?//'
}

# ----------------------------- Dispatcher ----------------------------------
main() {
  local cmd="${1:-install}"
  case "$cmd" in
    install|"")
      shift || true
      do_install "$@"
      # --start opcional: inicia logo apos instalar
      if [ "${1:-}" = "--start" ]; then
        echo " "; do_run
      fi
      ;;
    --start)
      do_install
      echo " "; do_run
      ;;
    run|start)
      do_run
      ;;
    status)
      do_status
      ;;
    uninstall|remove)
      do_uninstall
      ;;
    help|-h|--help)
      show_help
      ;;
    *)
      err "Comando desconhecido: $cmd"
      show_help
      exit 1
      ;;
  esac
}

main "$@"
exit 0
